record.field:
# Copy the old Income Statement module's data into this module: Income Statement
# Accounts (mapping) and Budget Allocation (budgets with their lines), record for
# record. Run it before uninstalling the old module; uninstalling drops its tables.
# Then every dashboard (or the selected ones) takes its accounts from the mapping.
has_mapping = bool(env['ir.model'].sudo().search_count([('model', '=', 'income.statement.account.mapping')]))
has_budget = bool(env['ir.model'].sudo().search_count([('model', '=', 'income.statement.budget')]))
if not has_mapping and not has_budget:
    raise UserError("The old Income Statement module is not installed, so there is nothing to "
                    "import. If it was already uninstalled, its mapping and budgets are gone.")
mapped = 0
budgets_copied = 0
if has_mapping:
    for old in env['income.statement.account.mapping'].sudo().search([]):
        current = env['x_isr_mapping'].sudo().search([('x_company_id', '=', old.company_id.id), ('x_row_key', '=', old.row_key)], limit=1)
        values = {'x_company_id': old.company_id.id, 'x_row_key': old.row_key, 'x_account_ids': [(6, 0, old.account_ids.ids)]}
        if current:
            current.write(values)
        else:
            env['x_isr_mapping'].sudo().create(values)
        mapped += 1
if has_budget:
    for old in env['income.statement.budget'].sudo().search([]):
        year_text = str(old.year or '')[:4]
        if not year_text.isdigit():
            continue
        year = int(year_text)
        if env['x_isr_budget'].sudo().search_count([('x_company_id', '=', old.company_id.id), ('x_year', '=', year),
                                                   ('x_quarter', '=', old.quarter)]):
            continue
        lines = []
        for line in old.line_ids:
            lines.append((0, 0, {'x_sequence': line.sequence, 'x_line_type': line.line_type, 'x_percentage': line.percentage}))
        env['x_isr_budget'].sudo().create({
            'x_company_id': old.company_id.id, 'x_year': year, 'x_quarter': old.quarter,
            'x_sales_revenue': old.sales_revenue, 'x_state': 'confirmed' if old.state == 'confirmed' else 'draft',
            'x_line_ids': lines,
        })
        budgets_copied += 1

# dashboards: accounts from the mapping just copied
targets = records or (record and [record]) or []
for dashboard in targets:
    dashboard = dashboard.sudo()
    for line in dashboard.x_line_ids:
        if line.x_kind != 'mapped':
            continue
        company_ids = (dashboard.x_company_id | dashboard.x_peer_company_ids).ids
        mappings = env['x_isr_mapping'].sudo().search([('x_company_id', 'in', company_ids), ('x_row_key', '=', line.x_key)])
        if mappings and mappings.mapped('x_account_ids'):
            accounts = mappings.mapped('x_account_ids')
            line.write({'x_account_ids': [(6, 0, accounts.ids)]})

if not env.context.get('isr_quiet'):
    action = {
        'type': 'ir.actions.client', 'tag': 'display_notification',
        'params': {'title': 'Imported from the old Income Statement', 'type': 'success', 'sticky': True,
                   'message': '%s account mapping(s) and %s budget(s) copied. Click Refresh Data.' % (mapped, budgets_copied)},
    }
